+    let cooldownMs = TOKEN_ENDPOINT_COOLDOWN_MS;
+    if (retryAfter) {
+      const seconds = Number(retryAfter);
+      if (Number.isFinite(seconds)) {
+        cooldownMs = Math.max(seconds * 1000, TOKEN_ENDPOINT_COOLDOWN_MS);
+      } else {
+        const retryAt = Date.parse(retryAfter);
+        if (Number.isFinite(retryAt)) {
+          cooldownMs = Math.max(retryAt - Date.now(), TOKEN_ENDPOINT_COOLDOWN_MS);
