        child.on("close", (code) => {
          if (code !== 0) {
            const errorMessage = (stderr.trim() || stdout.trim() || `cursor-agent exited with code ${code}`).trim();
            const errorPayload = {
              error: {
                message: `cursor-agent error: ${errorMessage}`,
                type: "server_error",
                code: "cursor_agent_failed",
              },
            };

            if (isStream) {
              // For streams, simply ending the connection is a safe way to signal an error.
              if (res.writable) res.end();
            } else {
              res.writeHead(502, { "Content-Type": "application/json" });
              res.end(JSON.stringify(errorPayload));
            }
            return;
          }

          const content = stdout.trim() || "(empty response)";

          if (isStream) {
            res.writeHead(200, {
