+  // Rotate to the best available account (LRU)
+  const sorted = [...accounts]
+    .filter(
+      (a) =>
+        (a.status === "active" || a.status === "idle") &&
+        (!a.cooldownUntil || a.cooldownUntil <= now),
+    )
+    .sort((a, b) => new Date(a.lastUsed || 0) - new Date(b.lastUsed || 0));
