+  for (const candidate of sorted) {
+    const token = await ensureValidToken("google", candidate);
+    if (token) {
+      activeAccountEmail = candidate.email;
+      patchAccount("google", candidate.email, {
+        lastUsed: new Date().toISOString(),
+        status: "active",
